/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: contrastRatio, rgbToOklab, artworkToneFromOklab, dominantArtworkColor, sampleArtworkTone
 * Internal
 *   Types: Rgb, Lab, ColorSum
 *   Functions: toLinear, toChannel, luminance, contrast, parseHex, toHex, oklchToLinear, inGamut, oklchToRgb,
 *              toneForText, emptySum, addSum
 *   Constants: white, mutedText, minimumContrast, maximumChroma, minimumLightness, sampleSize, hueBins
 * @end-catalog */

import type { ArtworkTone } from './useArtworkTone';

/** 8-bit sRGB channels. */
type Rgb = readonly [number, number, number];
/** OKLab lightness and opponent axes. */
type Lab = readonly [number, number, number];

const white: Rgb = [255, 255, 255];
/** The listener's muted text (#b3b3b3), which must stay legible on the darker pane tone. */
const mutedText: Rgb = [179, 179, 179];
/** WCAG AA for normal text is 4.5:1; the margin absorbs 8-bit rounding of the final colour. */
const minimumContrast = 4.6;
/** Keeps tones rich without neon extremes. */
const maximumChroma = 0.16;
/** Keeps dark artwork from producing an invisible, near-black tone. */
const minimumLightness = 0.28;
/** Drawing the 96 px variant this small averages noise and keeps sampling under a millisecond. */
const sampleSize = 24;

const toLinear = (channel: number) => {
  const value = channel / 255;
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
};

const toChannel = (linear: number) => {
  const value = linear <= 0.0031308 ? linear * 12.92 : 1.055 * linear ** (1 / 2.4) - 0.055;
  return Math.round(Math.min(1, Math.max(0, value)) * 255);
};

const luminance = ([red, green, blue]: Rgb) => (
  0.2126 * toLinear(red) + 0.7152 * toLinear(green) + 0.0722 * toLinear(blue)
);

const contrast = (first: Rgb, second: Rgb) => {
  const [lighter, darker] = [luminance(first), luminance(second)].sort((left, right) => right - left);
  return (lighter + 0.05) / (darker + 0.05);
};

const parseHex = (color: string): Rgb => {
  const value = Number.parseInt(color.replace('#', ''), 16);
  return [(value >> 16) & 255, (value >> 8) & 255, value & 255];
};

const toHex = (color: Rgb) => `#${color.map((channel) => channel.toString(16).padStart(2, '0')).join('')}`;

/** Returns the WCAG 2 contrast ratio between two `#rrggbb` colours. */
export const contrastRatio = (first: string, second: string) => contrast(parseHex(first), parseHex(second));

/** Converts 8-bit sRGB to OKLab, the perceptual space used for every tone decision. */
export const rgbToOklab = ([red, green, blue]: Rgb): Lab => {
  const [r, g, b] = [toLinear(red), toLinear(green), toLinear(blue)];
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [
    0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s
  ];
};

/** Converts OKLCH to linear sRGB, which falls outside 0–1 when the colour is out of gamut. */
const oklchToLinear = (lightness: number, chroma: number, hue: number) => {
  const a = chroma * Math.cos(hue);
  const b = chroma * Math.sin(hue);
  const l = (lightness + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (lightness - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (lightness - 0.0894841775 * a - 1.291485548 * b) ** 3;
  return [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s
  ];
};

const inGamut = (linear: number[]) => linear.every((channel) => channel >= -1e-4 && channel <= 1 + 1e-4);

/** Maps OKLCH into sRGB by reducing chroma only, so hue and lightness survive gamut mapping. */
const oklchToRgb = (lightness: number, chroma: number, hue: number): Rgb => {
  let fitted = chroma;
  if (!inGamut(oklchToLinear(lightness, chroma, hue))) {
    let low = 0;
    let high = chroma;
    for (let step = 0; step < 16; step += 1) {
      const middle = (low + high) / 2;
      if (inGamut(oklchToLinear(lightness, middle, hue))) low = middle;
      else high = middle;
    }
    fitted = low;
  }
  const [red, green, blue] = oklchToLinear(lightness, fitted, hue);
  return [toChannel(red), toChannel(green), toChannel(blue)];
};

/** Lowers OKLCH lightness, keeping hue and capped chroma, until `text` keeps AA contrast on the tone. */
const toneForText = (lightness: number, chroma: number, hue: number, text: Rgb) => {
  const legible = (candidate: number) => contrast(oklchToRgb(candidate, chroma, hue), text) >= minimumContrast;
  let low = 0;
  let high = Math.max(lightness, minimumLightness);
  if (legible(high)) return toHex(oklchToRgb(high, chroma, hue));
  for (let step = 0; step < 16; step += 1) {
    const middle = (low + high) / 2;
    if (legible(middle)) low = middle;
    else high = middle;
  }
  return toHex(oklchToRgb(low, chroma, hue));
};

/**
 * Derives both tone surfaces from one OKLab colour: `hero` keeps white text at AA, and the darker
 * `pane` also keeps muted text at AA, so ordinary page copy can sit on the main-pane gradient.
 */
export const artworkToneFromOklab = ([lightness, a, b]: Lab): ArtworkTone => {
  const chroma = Math.min(Math.hypot(a, b), maximumChroma);
  const hue = Math.atan2(b, a);
  return {
    hero: toneForText(lightness, chroma, hue, white),
    pane: toneForText(lightness, chroma, hue, mutedText)
  };
};

/** Weighted OKLab sums for one group of pixels. */
interface ColorSum {
  weight: number;
  l: number;
  a: number;
  b: number;
}

const emptySum = (): ColorSum => ({ weight: 0, l: 0, a: 0, b: 0 });

const addSum = (total: ColorSum, part: ColorSum) => {
  total.weight += part.weight;
  total.l += part.l;
  total.a += part.a;
  total.b += part.b;
};

/** Ten-degree hue bins; a colour family is scored over a 30° window of three neighbouring bins. */
const hueBins = 36;

/**
 * Finds the artwork's most prominent colour family. Near-grey pixels share one bin; chromatic
 * pixels are weighted by chroma and grouped by hue, so a vivid subject can outweigh a slightly
 * larger grey field. Families are scored as sliding 30° windows across the hue circle, so a shaded
 * colour that straddles a bin edge (sRGB red sits right on one) is never split in two and outvoted
 * by a smaller colour. Transparent pixels are ignored.
 */
export const dominantArtworkColor = (pixels: Uint8ClampedArray): Lab | null => {
  const neutral = emptySum();
  const bins = Array.from({ length: hueBins }, emptySum);
  for (let index = 0; index + 3 < pixels.length; index += 4) {
    if (pixels[index + 3] < 128) continue;
    const [l, a, b] = rgbToOklab([pixels[index], pixels[index + 1], pixels[index + 2]]);
    const chroma = Math.hypot(a, b);
    const weight = 1 + chroma * 8;
    const bin = chroma < 0.04
      ? neutral
      : bins[Math.floor(((Math.atan2(b, a) + Math.PI) / (2 * Math.PI)) * hueBins) % hueBins];
    addSum(bin, { weight, l: l * weight, a: a * weight, b: b * weight });
  }
  let best = neutral;
  for (let center = 0; center < hueBins; center += 1) {
    const window = emptySum();
    for (const offset of [-1, 0, 1]) addSum(window, bins[(center + offset + hueBins) % hueBins]);
    if (window.weight > best.weight) best = window;
  }
  return best.weight > 0 ? [best.l / best.weight, best.a / best.weight, best.b / best.weight] : null;
};

/**
 * Decodes one same-origin managed WebP variant and derives its tone. Rejects when the image cannot
 * load or decode, or when a cross-origin response taints the canvas; resolves null when the
 * canvas is unavailable or every pixel is transparent.
 */
export const sampleArtworkTone = async (variantUrl: string): Promise<ArtworkTone | null> => {
  const image = new Image();
  image.decoding = 'async';
  image.src = variantUrl;
  await image.decode();
  const canvas = document.createElement('canvas');
  canvas.width = sampleSize;
  canvas.height = sampleSize;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  if (!context) return null;
  context.drawImage(image, 0, 0, sampleSize, sampleSize);
  const color = dominantArtworkColor(context.getImageData(0, 0, sampleSize, sampleSize).data);
  return color ? artworkToneFromOklab(color) : null;
};
